css:
/* 対象に噛ませて尻尾を内側へ刺す */
.balloon{position:absolute; top:-16px; left:36%; z-index:3;
  background:#fff; border:3px solid #12569e; border-radius:10px; padding:2px 12px}
.balloon::after{content:''; position:absolute; left:14px; bottom:-11px;
  width:14px; height:14px; background:#fff;
  border-left:3px solid #12569e; border-bottom:3px solid #12569e;
  transform:skewX(-25deg)}                   /* 斜めに歪ませると手描き感が出る */

/* 引き出し線で図と数字を直結 */
.callout{position:absolute; z-index:2; background:#fff; border-radius:4px;
  padding:6px 10px; box-shadow:0 1px 3px rgba(0,0,0,.15)}
.callout::after{content:""; position:absolute; left:50%; top:100%;
  width:1px; height:34px; background:#0d8ea3}
